   if(step.sequence!==i+1||!step.beforeState||!step.afterState||!step.action||typeof step.result?.ok!=='boolean'||!Array.isArray(step.changes)||!Array.isArray(step.events)||!Array.isArray(step.effectCommands))throw Error('研究ログの操作が不正です');
   if(JSON.stringify(step.beforeState)!==JSON.stringify(previous))throw Error('研究ログの連続性が壊れています');
   if(!step.result.ok && JSON.stringify(step.beforeState)!==JSON.stringify(step.afterState))throw Error('拒否操作に状態変更があります');
   if(JSON.stringify(diff(step.beforeState,step.afterState))!==JSON.stringify(step.changes))throw Error('研究ログの差分が一致しません');
